<script setup lang="ts">
import {formatUsageTokens as token} from '../../utils/usageTokenFormat'
import {useUsageText} from '../../composables/useUsageText'
const tr=useUsageText()
import {computed,ref} from 'vue'
const p=defineProps<{data:any}>();defineEmits(['select']);const open=ref(true)
const pad=computed(()=>{const day=new Date(p.data.days[0]?.date+'T00:00:00Z').getUTCDay();return (day+6)%7});const values=computed(()=>p.data.days.map((d:any)=>Number(d.total??0)).filter((n:number)=>n>0).sort((a:number,b:number)=>a-b))
function color(d:any){if(d.total===null)return 'repeating-linear-gradient(135deg,var(--soft) 0 3px,var(--line) 3px 5px)';const n=Number(d.total);if(!n)return 'var(--soft)';const v=values.value;return `color-mix(in srgb,var(--accent) ${25+25*[.25,.5,.75].filter(q=>n>v[Math.floor(v.length*q)]).length}%,var(--panel))`}
const months=computed(()=>{const cells=[...Array(pad.value).fill(null),...p.data.days];let previous='';return Array.from({length:Math.ceil(cells.length/7)},(_,i)=>{const date=cells.slice(i*7,i*7+7).find(Boolean)?.date??'';const month=date.slice(0,7),label=month!==previous?month:'';previous=month;return {month,label}})})
</script>
<template><section class="pu-box"><header class="pu-boxhead"><h3>{{tr('最近90天活动')}}</h3><button class="pu-reset" :aria-expanded="open" @click="open=!open">{{open?tr('折叠'):tr('展开')}}</button></header><div v-show="open" class="pu-pad"><div class="heat-layout"><div class="heat-weekdays"><span v-for="day in ['一','二','三','四','五','六','日']" :key="day">{{tr('周'+day)}}</span></div><div><div class="heat-months"><span v-for="(m,i) in months" :key="i">{{m.label}}</span></div><div class="calendar"><span v-for="n in pad" :key="'p'+n"/><button v-for="d in data.days" :key="d.date" :style="{background:color(d)}" :class="{today:d.date===data.to_exclusive.slice(0,10),gap:d.total===null}" :title="`${d.date}: ${d.total===null?tr('未采集'):token(d.total)}`" :aria-label="`${d.date}: ${d.total===null?tr('未采集'):token(d.total)}`" @click="$emit('select',d,$event)"/></div></div></div><p class="pu-note">{{data.requested_from.slice(0,10)}} — {{data.to_exclusive.slice(0,10)}} · {{tr('UTC · 周一至周日')}}</p><p class="pu-note">{{tr('有消耗')}} {{data.active_days}} {{tr('天')}} · {{tr('最高单日')}} {{token(data.peak?.total)}}（{{data.peak?.date??tr('未采集')}}）</p><p class="pu-note">{{tr('灰：确认零 · 斜线：未采集 · 主色浅至深：当前90天非零四分位')}}</p></div></section></template>
<style scoped>.heat-layout{display:grid;grid-template-columns:30px minmax(0,1fr);gap:5px}.heat-weekdays{display:grid;grid-template-rows:repeat(7,20px);gap:4px;padding-top:22px;font-size:10px;color:var(--muted)}.heat-months{display:flex;height:22px;font-size:10px;color:var(--muted)}.heat-months span{flex:1;min-width:0;overflow:visible;white-space:nowrap}.calendar{display:grid;grid-template-rows:repeat(7,20px);grid-auto-flow:column;grid-auto-columns:1fr;gap:4px}.calendar button{border:1px solid transparent;border-radius:3px;cursor:pointer;min-width:0}.calendar .gap{border:1px solid var(--line)}.calendar .today{outline:2px solid var(--accent);outline-offset:1px}</style>
